def test_increment_consistency():
    # adding a[n+1] adds exactly the new triples ending at n+1
    for n in range(1, 30):
        a = [i * i - i + 1 for i in range(1, n + 2)]
        new_val = a[-1]
        added = 0
        for i in range(n):
            for j in range(i + 1, n):
                if (a[i] + a[j] + new_val) % 3 == 0:
                    added += 1
        assert get_max_triples(n + 1) == get_max_triples(n) + added
